CREATE TABLE gmail_connections (id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,google_email VARCHAR(320),encrypted_refresh_token TEXT,encrypted_access_token TEXT,access_token_expires_at TIMESTAMPTZ,status VARCHAR(30) NOT NULL,oauth_state VARCHAR(200),state_expires_at TIMESTAMPTZ,last_history_id VARCHAR(200),connected_at TIMESTAMPTZ,updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT uq_gmail_connection_user UNIQUE(user_id));
CREATE INDEX idx_gmail_connection_state ON gmail_connections(oauth_state);
CREATE TABLE ingested_emails (id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,gmail_message_id VARCHAR(200) NOT NULL,thread_id VARCHAR(200),from_addr VARCHAR(320),subject VARCHAR(1000),snippet TEXT,received_at TIMESTAMPTZ,category VARCHAR(60),processed_at TIMESTAMPTZ,CONSTRAINT uq_ingested_email UNIQUE(user_id,gmail_message_id));
CREATE INDEX idx_ingested_emails_user_received ON ingested_emails(user_id,received_at);